/**
 * Confluence Node - Version 1
 * Discriminator: resource=attachment, operation=upload
 */


interface Credentials {
  confluenceCloudOAuth2Api: CredentialReference;
  atlassianServiceAccountApi: CredentialReference;
}

/** Upload a file as an attachment on a page */
export type ConfluenceV1AttachmentUploadParams = {
  resource: 'attachment';
  operation: 'upload';
  authentication?: 'cloudOAuth2' | 'serviceAccount';
/**
 * The Confluence site to use. Can be left empty when the connection has access to exactly one site.
 * @searchListMethod getSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url'; value: string; cachedResultName?: string };
/**
 * Limits page selection and By Title lookups to one space. Leave empty or pick "All Spaces" to search across all spaces.
 * @searchListMethod searchSpacesWithAll
 * @default {"mode":"list","value":""}
 */
    space?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The page to attach the file to
 * @searchListMethod getPages
 * @default {"mode":"list","value":""}
 */
    page?: { __rl: true; mode: 'list' | 'url' | 'id' | 'title'; value: string; cachedResultName?: string };
/**
 * The name of the input binary field containing the file to upload
 * @hint The file is loaded into memory in full before uploading, so very large files may be slow or use significant memory
 * @default data
 */
    binaryPropertyName?: string | Expression<string>;
/**
 * Whether to upload without notifying watchers of the page
 * @default false
 */
    minorEdit?: boolean | Expression<boolean>;
/**
 * An optional comment to attach to this version of the file
 */
    comment?: string | Expression<string>;
};

export type ConfluenceV1AttachmentUploadNode = {
  type: 'n8n-nodes-base.confluence';
  version: 1;
  config: NodeConfig<ConfluenceV1AttachmentUploadParams> & { credentials?: Credentials };
};